set -u
R=/scratch/jjyeung/orch_n30
date -u +%TZ; free -g | sed -n 2p
mkdir -p $R/sb_kobj/prompts $R/sb_kobj/out
echo  | base64 -d > $R/sb_kobj/prompts/sb_kobj.md
echo sb_kobj >> $R/sb_queue/queue.txt
tail -4 $R/sb_queue/codexq.log; cat $R/sb_queue/queue.txt | tr "\n" " "; echo
pgrep -f "codex_dispatch.sh implement $R/sb_" -a | grep -o "label [a-zA-Z0-9_]*" | sort -u | tr "\n" " "; echo
for s in sb_arev2 sb_brev3 sb_afrev sb_fprev sb_rlrev sb_recrev sb_f64; do echo "$s log=$(wc -c < $R/$s/cursor.log) verdict=$(ls $R/$s/REVIEW_VERDICT.md 2>/dev/null) newest=$(ls -t $R/$s | head -1)"; done
for t in sb_rowOI sb_roomkit sb_rowD5 sb_regenscope sb_harev; do d=$(ls -d $R/codex_local/agent/scratch/codex_runs/*_$t 2>/dev/null | tail -1); echo "== $t"; [ -f $d/final_message.md ] && head -c 900 $d/final_message.md; head -c 300 $R/$t/STATUS.md 2>/dev/null; echo; done
